#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSshSessionHandle: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = SshSessionHandle

    public static func lift(_ handle: UInt64) throws -> SshSessionHandle {
        return SshSessionHandle(unsafeFromHandle: handle)
    }

    public static func lower(_ value: SshSessionHandle) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SshSessionHandle {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: SshSessionHandle, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSshSessionHandle_lift(_ handle: UInt64) throws -> SshSessionHandle {
    return try FfiConverterTypeSshSessionHandle.lift(handle)
}

#if swift(>=5.8)
